<?= $this->extend('layouts/store') ?><?= $this->section('content') ?><section class="narrow"><p class="eyebrow">Order #<?= $order['id'] ?></p><h1><?= ucfirst($order['status']) ?>.</h1><p>Payment: <?= ucfirst($order['payment_status']) ?></p><?php foreach($items as $i): ?><div class="cart-row"><strong><?= esc($i['product_name']) ?></strong><span>Qty <?= $i['quantity'] ?></span><strong>₹<?= number_format($i['price_at_purchase']*$i['quantity'],2) ?></strong></div><?php endforeach ?><div class="cart-total"><span>Total</span><strong>₹<?= number_format($order['total_amount'],2) ?></strong></div></section><?= $this->endSection() ?>
